async function chooseAudioEditor(resource) {
  const capabilities = hostCapabilities(); if (!capabilities.externalEditors) { vscode.window.showInformationMessage(missingCapabilityMessage('External audio editor selection', capabilities)); return ''; }
  const config = vscode.workspace.getConfiguration('ikemenZss', resource), current = config.get('audioEditorPath', '');
  const picked = await vscode.window.showOpenDialog({ title: 'Choose Audacity or another audio editor', canSelectMany: false, filters: { Applications: ['exe'] } });
  if (!picked || !picked[0]) return current;
  const target = configurationTarget(vscode, resource);
  await config.update('audioEditorPath', picked[0].fsPath, target);
  return picked[0].fsPath;
}

async function openProfile(filename) {
  let profilePath = soundProfile.locate(filename);
  if (!profilePath) {
    const root = characterRoot(filename), id = path.basename(root) || 'CHAR'; profilePath = path.join(root, soundProfile.PROFILE_FILENAME);
    const answer = await vscode.window.showInformationMessage(`Create a portable sound profile for ${id}?`, { modal: true, detail: 'This records split archives, native CommonFX prefixes, build manifests, and named sound events. It does not change the SND.' }, 'Create Profile');
    if (answer !== 'Create Profile') return;
    transactionalWrite(fs, profilePath, `${JSON.stringify(soundProfile.template(id), null, 2)}\n`, mutationOptions(profilePath, 'create-sound-profile', { allowExisting: false }));
  }
  await vscode.window.showTextDocument(vscode.Uri.file(profilePath), { preview: false });
}

async function openConnectedSnd(message, filename, ownerDefs, panel, api = vscode, closing = isClosingOwner) {
  const target = connectedAssetInventory(filename, ownerDefs || [], 'snd').find(item => item.id === message?.id);
  if (!target) { api.window.showWarningMessage('That connected SND is no longer available. Refresh the viewer and try again.'); return false; }
  if ((ownerDefs || []).some(closing)) { api.window.showWarningMessage('This character workbench is closing, so another SND was not opened.'); return false; }
  const opened = await api.commands.executeCommand('snd.openViewer', api.Uri.file(target.filename), panel.viewColumn, undefined, undefined, { ownerDefs });
  if (!opened) { api.window.showWarningMessage(`Could not focus ${path.basename(target.filename)}. The current SND viewer was left unchanged.`); return false; }
  return true;
}

